#include <bits/stdc++.h>
using namespace std;

int main() {
	int n, q;
	cin >> n >> q;
	vector<int> up(2 * n, -1), down(2 * n, -1);
	for (int i = 0; i < n; i++) up[n + i] = i, down[i] = n + i;
	while (q--) {
		int c, p;
		cin >> c >> p;
		c--; p--;
		int d = down[c];
		down[c] = p;
		up[p] = c;
		up[d] = -1;
	}
	for (int i = 0; i < n; i++) {
		int x = n + i, ans = 0;
		while (up[x] != -1) {
			x = up[x];
			ans++;
		}
		cout << ans << " \n"[i == n - 1];
	}
}

use {proconio::{input, marker::Usize1}, ac_library::Dsu};

fn main() {
    input! { N: usize, Q: usize, CP: [(Usize1, Usize1); Q] }

    let mut dsu = Dsu::new(N);
    let mut seen = vec![false; N];

    // 操作を逆順に見る
    // それまでに C_i = c として操作していなければ辺を張る
    for (C, P) in CP.into_iter().rev() {
        if !seen[C] { seen[C] = true; dsu.merge(C, P); }
    }

    for i in 0..N {
        print!("{} ", if seen[i] {0} else {dsu.size(i)});
    }
}
